@st.cache_data(show_spinner=False)
def get_data():
    df = load_books()
    X, feature_names = build_feature_matrix(df)
    engine = ContentRecommender(df, X, feature_names)
    return df, X, feature_names, engine.similarity_matrix


def _migrate_user(user: dict) -> tuple[dict, bool]:
    changed = False
    genres = []
    for genre in user.get("genres", []):
        mapped = OLD_GENRE_MAP.get(genre, genre)
        if mapped not in genres:
            genres.append(mapped)
        changed |= mapped != genre
    user["genres"] = genres
    for field, default in [
        ("favorites", []),
        ("ratings", {}),
        ("read_books", list(user.get("ratings", {}).keys())),
        ("profile_done", False),
        ("role", "reader"),
        ("avatar_type", "preset"),
        ("avatar_value", "🌙"),
    ]:
        if field not in user:
            user[field] = default
            changed = True
    return user, changed


def _supabase_settings():
    """Return cloud storage settings from Streamlit Secrets, if configured."""
    try:
        url = str(st.secrets.get("supabase_url", "")).strip()
        key = str(st.secrets.get("supabase_secret_key", "")).strip()
        table = str(st.secrets.get("supabase_table", "moon_ruler_users")).strip() or "moon_ruler_users"
    except Exception:
        return "", "", "moon_ruler_users"
    return url, key, table


@st.cache_resource(show_spinner=False)
def _supabase_client():
    """Create one server-side Supabase client. Returns None when cloud storage is not configured."""
    url, key, _ = _supabase_settings()
    if not url or not key:
        return None
    try:
        from supabase import create_client
        return create_client(url, key)
    except Exception:
        return None


def cloud_storage_enabled():
    url, key, _ = _supabase_settings()
    return bool(url and key)


def cloud_storage_diagnostics(test_write=False):
    """Return a readable health report for the configured Supabase backend.

    When ``test_write`` is True, a temporary probe row is inserted and deleted to
    verify that the configured server-side key can both read and write the table.
    """
    url, key, table = _supabase_settings()
    report = {
        "configured": bool(url and key),
        "url": bool(url),
        "key": bool(key),
        "table": table,
        "client": False,
        "read": False,
        "write": None,
        "error": "",
    }
    if not report["configured"]:
        report["error"] = "Missing supabase_url or supabase_secret_key in Streamlit Secrets."
        return report

    client = _supabase_client()
    if client is None:
        report["error"] = (
            "Supabase client could not be created. Check that the 'supabase' package is installed "
            "and that the URL/key are valid."
        )
        return report

    report["client"] = True
    try:
        client.table(table).select("username").limit(1).execute()
        report["read"] = True
        if test_write:
            probe = "__moon_ruler_storage_probe__"
            now = datetime.now(timezone.utc).isoformat()
            client.table(table).upsert(
                {"username": probe, "data": {"probe": True}, "updated_at": now},
                on_conflict="username",
            ).execute()
            client.table(table).delete().eq("username", probe).execute()
            report["write"] = True
    except Exception as exc:
        report["error"] = str(exc)
        if test_write:
            report["write"] = False
    return report


def _load_users_from_cloud():
    client = _supabase_client()
    if client is None:
        return None
    _, _, table = _supabase_settings()
    try:
        response = client.table(table).select("username,data").execute()
        users = {}
        for row in (response.data or []):
            username = str(row.get("username", "")).strip().lstrip("@").lower()
            payload = row.get("data")
            if username and isinstance(payload, dict):
                users[username] = payload
        return users
    except Exception as exc:
        st.session_state["cloud_storage_error"] = f"Cloud storage read failed: {exc}"
        return None


def _save_users_to_cloud(users):
    client = _supabase_client()
    if client is None:
        return False
    _, _, table = _supabase_settings()
    try:
        now = datetime.now(timezone.utc).isoformat()
        rows = [
            {"username": str(username).strip().lstrip("@").lower(), "data": user, "updated_at": now}
            for username, user in users.items()
        ]
        if rows:
            client.table(table).upsert(rows, on_conflict="username").execute()

        # Keep account deletion behavior consistent with the local JSON backend.
        existing = client.table(table).select("username").execute().data or []
        desired = {str(u).strip().lstrip("@").lower() for u in users}
        for row in existing:
            username = str(row.get("username", "")).strip().lstrip("@").lower()
            if username and username not in desired:
                client.table(table).delete().eq("username", username).execute()
        st.session_state.pop("cloud_storage_error", None)
        return True
    except Exception as exc:
        st.session_state["cloud_storage_error"] = f"Cloud storage write failed: {exc}"
        return False


def _save_user_to_cloud(username, user):
    """Upsert one account only. Used for normal reader interactions."""
    client = _supabase_client()
    if client is None:
        return False
    _, _, table = _supabase_settings()
    try:
        username = str(username).strip().lstrip("@").lower()
        now = datetime.now(timezone.utc).isoformat()
        client.table(table).upsert(
            {"username": username, "data": user, "updated_at": now},
            on_conflict="username",
        ).execute()
        st.session_state.pop("cloud_storage_error", None)
        st.session_state.pop("cloud_storage_fallback", None)
        return True
    except Exception as exc:
        st.session_state["cloud_storage_error"] = f"Cloud storage write failed: {exc}"
        return False


def _delete_user_from_cloud(username):
    """Delete one account from Supabase without scanning the whole table."""
    client = _supabase_client()
    if client is None:
        return False
    _, _, table = _supabase_settings()
    try:
        username = str(username).strip().lstrip("@").lower()
        client.table(table).delete().eq("username", username).execute()
        st.session_state.pop("cloud_storage_error", None)
        return True
    except Exception as exc:
        st.session_state["cloud_storage_error"] = f"Cloud storage delete failed: {exc}"
        return False


def _read_admin_registry(path):
    if not path.exists():
        return set()
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(raw, dict):
            raw = raw.get("admins", [])
        return {str(u).strip().lower() for u in raw if str(u).strip()}
    except Exception:
        return set()


def _secret_admins():
    """Read optional admin usernames from Streamlit Secrets for cloud deployment."""
    try:
        raw = st.secrets.get("admin_usernames", [])
    except Exception:
        return set()
    if isinstance(raw, str):
        raw = [raw]
    return {str(u).strip().lstrip("@").lower() for u in raw if str(u).strip()}


def load_admins():
    """Load admin usernames from project, local-machine, and cloud-secret registries.

    Local development persists admins in data/admins.json and ~/.moon_ruler/admins.json.
    Streamlit Community Cloud can bootstrap admins from the `admin_usernames` secret.
    """
    admins = (
        _read_admin_registry(ADMINS_PATH)
        | _read_admin_registry(USER_ADMIN_REGISTRY_PATH)
        | _secret_admins()
    )
    return admins


def save_admins(admins):
    payload = json.dumps({"admins": sorted(set(admins))}, indent=2, ensure_ascii=False)
    ADMINS_PATH.parent.mkdir(parents=True, exist_ok=True)
    ADMINS_PATH.write_text(payload, encoding="utf-8")
    try:
        USER_ADMIN_REGISTRY_PATH.parent.mkdir(parents=True, exist_ok=True)
        USER_ADMIN_REGISTRY_PATH.write_text(payload, encoding="utf-8")
    except OSError:
        # Project-level registry still works on restricted environments.
        pass


def load_users(force=False):
    """Load accounts, using an in-session cache to avoid repeated network reads.

    Supabase is contacted once at the beginning of a browser session (or when
    ``force=True``). Normal Streamlit reruns reuse the cached dictionary.
    """
    if not force and "_users_cache" in st.session_state:
        return st.session_state["_users_cache"]

    users = _load_users_from_cloud() if cloud_storage_enabled() else None
    if users is None:
        if not USERS_PATH.exists():
            users = {}
        else:
            users = json.loads(USERS_PATH.read_text(encoding="utf-8"))

    admins = load_admins()
    changed = False
    registry_changed = False
    for key, user in users.items():
        users[key], did_change = _migrate_user(user)
        changed |= did_change
        if users[key].get("role") == "admin" and key not in admins:
            admins.add(key)
            registry_changed = True
        if key in admins and users[key].get("role") != "admin":
            users[key]["role"] = "admin"
            changed = True
    if registry_changed:
        save_admins(admins)

    st.session_state["_users_cache"] = users
    if changed:
        # Migration writes are rare and happen only on the first load.
        save_users(users)
    return users


def refresh_users_from_storage():
    """Explicitly refresh the session cache from Supabase/local storage."""
    st.session_state.pop("_users_cache", None)
    return load_users(force=True)


def save_users(users):
    """Persist a full account collection for rare admin/bulk operations.

    Normal reader actions use ``save_user`` so they only upsert one row.
    """
    st.session_state["_users_cache"] = users
    if cloud_storage_enabled():
        if _save_users_to_cloud(users):
            st.session_state.pop("cloud_storage_fallback", None)
            return
        USERS_PATH.parent.mkdir(parents=True, exist_ok=True)
        USERS_PATH.write_text(json.dumps(users, indent=2, ensure_ascii=False), encoding="utf-8")
        st.session_state["cloud_storage_fallback"] = True
        return
    USERS_PATH.parent.mkdir(parents=True, exist_ok=True)
    USERS_PATH.write_text(json.dumps(users, indent=2, ensure_ascii=False), encoding="utf-8")


def save_user(username, user):
    """Persist one user and update the in-session cache immediately."""
    username = str(username).strip().lstrip("@").lower()
    users = load_users()
    users[username] = user
    st.session_state["_users_cache"] = users

    if cloud_storage_enabled():
        if _save_user_to_cloud(username, user):
            return True
        USERS_PATH.parent.mkdir(parents=True, exist_ok=True)
        USERS_PATH.write_text(json.dumps(users, indent=2, ensure_ascii=False), encoding="utf-8")
        st.session_state["cloud_storage_fallback"] = True
        return False

    USERS_PATH.parent.mkdir(parents=True, exist_ok=True)
    USERS_PATH.write_text(json.dumps(users, indent=2, ensure_ascii=False), encoding="utf-8")
    return True


def delete_user(username):
    """Delete one account efficiently and remove it from the session cache."""
    username = str(username).strip().lstrip("@").lower()
    users = load_users()
    users.pop(username, None)
    st.session_state["_users_cache"] = users
    if cloud_storage_enabled():
        return _delete_user_from_cloud(username)
    USERS_PATH.parent.mkdir(parents=True, exist_ok=True)
    USERS_PATH.write_text(json.dumps(users, indent=2, ensure_ascii=False), encoding="utf-8")
    return True


def set_admin_role(username, make_admin=True):
    username = username.strip().lstrip("@").lower()
    users = load_users()
    if username not in users:
        raise KeyError(username)
    admins = load_admins()
    if make_admin:
        admins.add(username)
        users[username]["role"] = "admin"
    else:
        admins.discard(username)
        users[username]["role"] = "reader"
    save_admins(admins)
    save_user(username, users[username])


def effective_role(username, user=None):
    if username in load_admins():
        return "admin"
    return (user or {}).get("role", "reader")


def hash_password(password, salt):
    return hashlib.sha256((salt + password).encode("utf-8")).hexdigest()


def current_user():
    return load_users()[st.session_state.username]


def update_user(**changes):
    username = st.session_state.username
    users = load_users()
    user = users[username]
    dirty = any(user.get(key) != value for key, value in changes.items())
    if not dirty:
        return
    user.update(changes)
    save_user(username, user)

def age_from(iso_date):
    born, today = date.fromisoformat(iso_date), date.today()
    return today.year - born.year - ((today.month, today.day) < (born.month, born.day))


def genres_for_scope(df, scope):
    categories = ["Fiction", "Academics"] if scope == "Free Reader" else [scope]
    return [g for g in df["genre"].drop_duplicates() if df.loc[df["genre"] == g, "category"].iloc[0] in categories]


def avatar_markup(user, size=82):
    """Return safe HTML for a preset emoji or uploaded JPG/PNG avatar."""
    if user.get("avatar_type") == "custom" and str(user.get("avatar_value", "")).startswith("data:image/"):
        src = html.escape(user["avatar_value"], quote=True)
        return f'<img class="avatar-img" src="{src}" alt="Profile picture" style="width:{size}px;height:{size}px">'
    avatar = html.escape(str(user.get("avatar_value", "🌙")))
    return f'<div class="avatar-ring" style="width:{size}px;height:{size}px">{avatar}</div>'


def image_file_to_data_uri(uploaded):
    if uploaded is None:
        return None
    if uploaded.type not in {"image/png", "image/jpeg"}:
        raise ValueError("Please upload a JPG or PNG image.")
    data = uploaded.getvalue()
    if len(data) > 2 * 1024 * 1024:
        raise ValueError("Profile pictures must be 2 MB or smaller.")
    return f"data:{uploaded.type};base64,{base64.b64encode(data).decode('ascii')}"


def fallback_cover_data_uri(title, author=""):
    safe_title = html.escape(str(title)[:36])
    safe_author = html.escape(str(author)[:28])
    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" width="240" height="360" viewBox="0 0 240 360">'
        '<rect width="240" height="360" rx="10" fill="#E7C77E"/>'
        '<rect x="8" y="8" width="224" height="344" rx="8" fill="none" stroke="#76543A" stroke-width="3"/>'
        f'<text x="120" y="135" text-anchor="middle" font-family="Georgia,serif" font-size="18" fill="#2F2018">{safe_title}</text>'
        f'<text x="120" y="235" text-anchor="middle" font-family="Georgia,serif" font-size="12" fill="#6D5138">{safe_author}</text>'
        '<text x="120" y="325" text-anchor="middle" font-family="Georgia,serif" font-size="16" fill="#76543A">MOON RULER</text>'
        '</svg>'
    )
    return "data:image/svg+xml;utf8," + quote(svg)


@st.cache_data(ttl=60 * 10, show_spinner=False)
def cover_service_available():
    """Probe Open Library once so offline use does not wait on every book card."""
    try:
        req = Request("https://openlibrary.org/", headers={"User-Agent": "MoonRuler/1.0"})
        with urlopen(req, timeout=1.2) as response:
            return 200 <= getattr(response, "status", 200) < 500
    except Exception:
        return False


@st.cache_data(ttl=60 * 60 * 24, show_spinner=False)
def get_book_cover(title, author=""):
    """Resolve a cover through Open Library and fall back to a local title card."""
    if not cover_service_available():
        return fallback_cover_data_uri(title, author)
    try:
        params = urlencode({"title": str(title), "author": str(author), "limit": 1, "fields": "cover_i,title,author_name"})
        req = Request("https://openlibrary.org/search.json?" + params, headers={"User-Agent": "MoonRuler/1.0"})
        with urlopen(req, timeout=2.5) as response:
            payload = json.loads(response.read().decode("utf-8"))
        docs = payload.get("docs", [])
        if docs and docs[0].get("cover_i"):
            return f"https://covers.openlibrary.org/b/id/{docs[0]['cover_i']}-M.jpg"
    except Exception:
        pass
    return fallback_cover_data_uri(title, author)


@st.cache_data(show_spinner=False)
def genre_icon_data_uri(genre):
    """Return a bundled PNG genre icon as a browser-safe data URI."""
    filename = GENRE_ICONS.get(genre)
    if not filename:
        return ""
    path = GENRE_ICON_DIR / filename
    if not path.exists():
        return ""
    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:image/png;base64,{encoded}"


def genre_icon_html(genre, css_class="genre-inline-icon", alt=True):
    src = genre_icon_data_uri(genre)
    if not src:
        return ""
    alt_text = html.escape(genre) if alt else ""
    return f'<img class="{css_class}" src="{src}" alt="{alt_text}">'


def genre_meta_html(genre):
    return f'{genre_icon_html(genre, "genre-meta-icon")}<span>{html.escape(genre)}</span>'


def render_genre_badge(genre):
    return (
        '<div class="genre-badge">'
        f'<div class="genre-badge-icon">{genre_icon_html(genre, "genre-badge-img")}</div>'
        f'<div class="genre-badge-title">{html.escape(genre)}</div>'
        '</div>'
    )


def render_genre_choice_icon(genre, selected=False):
    state = " selected" if selected else ""
    return (
        f'<div class="genre-choice-art{state}">'
        f'{genre_icon_html(genre, "genre-choice-img")}'
        '</div>'
    )


def choice_icon_data_uri(name):
    """Return a self-contained PNG data URI for onboarding choice icons.

    Icons are embedded directly in this Python file so deployment does not
    depend on a separate assets/choice_icons folder being uploaded.
    """
    encoded = EMBEDDED_CHOICE_ICONS.get(name, "")
    return f"data:image/png;base64,{encoded}" if encoded else ""


def choice_icon_html(name, css_class="choice-card-img", alt=True):
    src = choice_icon_data_uri(name)
    if not src:
        return ""
    alt_text = html.escape(name) if alt else ""
    return f'<img class="{css_class}" src="{src}" alt="{alt_text}">'


def render_choice_card_icon(name, selected=False):
    """Render main-choice icons with the exact same DOM/CSS classes as working subgenre icons."""
    state = " selected" if selected else ""
    src = choice_icon_data_uri(name)
    if not src:
        return ""
    alt_text = html.escape(name)
    return (
        f'<div class="genre-choice-art{state}">'
        f'<img class="genre-choice-img" src="{src}" alt="{alt_text}">'
        '</div>'
    )


def choice_icon_path(name):
    filename = CHOICE_ICONS.get(name)
    if not filename:
        return None
    path = CHOICE_ICON_DIR / filename
    return path if path.exists() else None


# -----------------------------------------------------------------------------
# Recommendation helpers
# -----------------------------------------------------------------------------
def user_taste(df, X, feature_names, user):
    engine = ContentRecommender(df, X, feature_names)
    return engine.build_user_vector(
        ratings=user.get("ratings", {}),
        favorites=user.get("favorites", []),
        genres=user.get("genres", []),
    )


def why_recommended(row, df, sim, user, personalized=True):
    """Explain the strongest evidence behind a recommendation in plain language."""
    if not personalized:
        return f"Discovery pick from {row['genre']}; no personal ratings are needed yet."

    liked = [t for t, r in user.get("ratings", {}).items() if r >= LIKED_THRESHOLD]
    liked += user.get("favorites", [])
    title_to_index = {t: i for i, t in enumerate(df["title"])}
    liked_idx = [title_to_index[t] for t in dict.fromkeys(liked) if t in title_to_index]

    if liked_idx:
        seed_idx = max(liked_idx, key=lambda i: sim[row.name][i])
        seed = df.iloc[seed_idx]
        evidence = []
        if seed["genre"] == row["genre"]:
            evidence.append(f"same genre as {seed['title']}")
        if seed["author"] == row["author"]:
            evidence.append(f"same author ({row['author']})")
        shared = sorted(set(seed["tags"]) & set(row["tags"]))
        if shared:
            evidence.append("shared themes: " + ", ".join(shared[:3]))
        if evidence:
            return "Because you liked or saved " + seed["title"] + ": " + "; ".join(evidence)

    if row["genre"] in user.get("genres", []):
        tag_hint = ", ".join(list(row["tags"])[:2])
        return f"Matches your {row['genre']} interest" + (f" · themes: {tag_hint}" if tag_hint else "")
    return "Fits the combined pattern of your genres, saved books, and ratings."


def find_books(df, query):
    q = query.strip().lower()
    if not q:
        return df.iloc[0:0]
    mask = (
        df["title"].str.lower().str.contains(q, regex=False)
        | df["author"].str.lower().str.contains(q, regex=False)
        | df["genre"].str.lower().str.contains(q, regex=False)
        | df["tags"].apply(lambda tags: any(q in t for t in tags))
    )
    return df[mask]


def profile_strength(user):
    signals = len(user.get("genres", [])) + len(user.get("favorites", [])) + len(user.get("read_books", [])) + len(user.get("ratings", {})) * 2
    return min(100, 15 + signals * 9)


